-- The home page "notice" section used to link to the News page. News is gone,
-- so repoint it at the new Membership Agreement page instead.
UPDATE page_sections
SET heading = 'Membership Agreement',
    body_html = '<p>Renewing or applying for membership? Read the Range Rules and sign the Membership Agreement online before you apply.</p>'
WHERE page_slug = 'home' AND section_key = 'notice';

-- Content for the new standalone Membership Agreement page (replaces News),
-- formatted after the legacy printed Range Rules / Agreement form.
INSERT INTO page_sections (page_slug, section_key, heading, body_html) VALUES
('agreement', 'intro', 'Membership Rules & Agreement', '<p>Please read the club Range Rules below, then sign to confirm you have read and agree to them.</p>'),
('agreement', 'body', NULL, '<ol class="rules-list"><li>Range flag at gate must be raised anytime you are on the property! Range flags at firing lines must be raised when shooting on the line or downrange.</li><li>All shooting on rifle ranges must be done from the permanent firing line.</li><li>I will not shoot when work crews are on the range.</li><li>I will follow all of the safety rules and guidelines I have been taught about safe gun handling. I am responsible for my guest''s actions while on the property.</li><li>I will not shoot center fire rifles, including .223 pistols, toward or in pistol ranges #1 and #2.</li><li>I will follow the club calendar, as scheduled events will take precedence.</li><li>I will not shoot with artificial lighting.</li><li>I will take all my targets and trash I brought to the range home, or deposit in trash cans provided. I WILL NOT LEAVE MY TARGETS ON THE BACKER BOARDS.</li><li>I will only shoot at targets that are safe, NOT trash cans, rocks or other items that may cause ricochets.</li><li>During scheduled shoots, modified rules may apply.</li><li>No hunting of any kind is allowed on club property.</li><li>Shotgun shooting is not allowed on club property. This includes handguns while shooting shot shells.</li><li>A member must accompany guests at all times.</li><li>Vehicles are allowed to be driven to the backstops to setup or check targets provided they stay on rock. No vehicles behind the backstops.</li><li>No alcoholic beverages are allowed on club property at any time.</li><li>Eye and Ear protection is required at all matches, we recommend using whenever you are shooting.</li><li>Do not leave live rounds lying on the range. Dispose of them in the misfire container located at the end of the backstop between ranges #1 and #2.</li><li>The use of binary explosives is prohibited. (Tannerite, Shockwave etc.)</li></ol><p>If you see someone violate these rules or act in an unsafe manner, it is suggested that you approach them in a nonthreatening manner and bring the violation to their attention. If you are not satisfied that they understand and will correct their actions, contact a club officer and a review of the incident will made by the board. As a member you have the right to ask to see their membership card.</p><p>This form must be signed and returned to the club along with payment of dues, address, phone number, e-mail address and proof of current NRA membership with expiration date. Failure to provide this information will result in non renewal of your club membership. Dues are due August 1st of each year. There is a grace period until 9/11 of each year. FAILURE TO PAY DUES BY SEPTEMBER 10TH WILL RESULT IN TERMINATION OF YOUR MEMBERSHIP.</p><p>At this time the dues are $150.00 yearly.</p><p>I have read these rules and I agree to abide by these rules. As safety is our primary concern, I understand that any violation of this rule by me or my guests could result in termination of my membership.</p><p>ALL NEW MEMBERS WILL HAVE TO COMPLETE A RANGE SAFETY ORIENTATION BEFORE BEING ISSUED THEIR MEMBER CARD.</p>');
